<template>
  <main class="content"><div class="title-row"><div><div class="eyebrow">平台运营 / 主办方管理 / 详情</div><h1>{{ organizer?.name || "主办方详情" }}</h1><p>查看机构资料、关联账号及旗下活动。</p></div><RouterLink class="back-link" to="/management/platform/organizers">返回主办方列表</RouterLink></div>
    <div v-if="loading" class="panel state">详情加载中...</div><div v-else-if="error" class="panel error">{{ error }} <button @click="load">重新加载</button></div>
    <template v-else-if="organizer"><section class="panel hero"><div class="avatar">{{ (organizer.name||"主").slice(0,1) }}</div><div><span class="status" :class="`status-${organizer.status}`">{{ labels[organizer.status] || organizer.status }}</span><h2>{{ organizer.name }}</h2><p>主办方 ID：{{ organizer.id }}</p></div></section><section class="panel"><h2>基础资料</h2><dl><div><dt>统一社会信用代码</dt><dd>{{ organizer.unifiedSocialCreditCode || "未填写" }}</dd></div><div><dt>联系人</dt><dd>{{ organizer.contactName }}</dd></div><div><dt>联系电话</dt><dd>{{ organizer.contactPhone }}</dd></div><div><dt>创建时间</dt><dd>{{ formatDate(organizer.createdAt) }}</dd></div><div><dt>最近更新时间</dt><dd>{{ formatDate(organizer.updatedAt) }}</dd></div><div><dt>审核时间</dt><dd>{{ formatDate(organizer.reviewedAt) }}</dd></div></dl></section><section class="panel"><div class="archive-heading"><h2>关联账号 · {{ accounts.length }} 个</h2><button v-if="organizer.status === 'APPROVED'" class="staff-action staff-primary" @click="creating=true">创建管理员账号</button></div><p class="staff-hint">账号状态与机构审核状态分别管理。停用和强制下线请前往用户管理。</p><p v-if="notice" class="staff-notice">{{ notice }}</p><table class="staff-table"><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td><StaffIdentity :account="a" :subtitle="a.username" /><small>{{ a.phone || '手机号未填写' }}</small></td><td>{{ a.role === 'ORGANIZER_ADMIN' ? '主办方管理员' : '核销员' }}</td><td>{{ a.enabled ? '正常' : '已停用' }}</td><td><RouterLink class="staff-action" :to="{path:'/management/platform/users',query:{keyword:a.username}}">管理账号</RouterLink></td></tr></tbody></table><p v-if="!accounts.length" class="staff-hint">暂无关联账号。</p></section><section class="panel"><h2>旗下活动 · {{ activities.length }} 个</h2><table class="staff-table"><thead><tr><th>活动</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in activities" :key="a.id"><td>{{ a.title }}</td><td>{{ {DRAFT:'草稿',PENDING:'待审核',PUBLISHED:'已上架',REJECTED:'已驳回',OFFLINE:'已下架',CANCELLED:'已取消'}[a.status] || a.status }}</td><td><RouterLink class="staff-action" :to="'/management/platform/activities/'+a.id">查看活动</RouterLink></td></tr></tbody></table><p v-if="!activities.length" class="staff-hint">暂无活动。</p></section><StaffAccountForm v-if="creating" :organizer-id="organizer.id" @close="creating=false" @created="created" /></template>
  </main>
</template>
<script setup>
import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { platformOrganizerApi } from "../../api/platformOrganizer";
const route=useRoute(),organizer=ref(null),loading=ref(true),error=ref("");const labels={PENDING:"待审核",APPROVED:"已通过",REJECTED:"已驳回",DISABLED:"已停用"};const formatDate=(v)=>v?new Date(v).toLocaleString("zh-CN",{hour12:false}):"-";
import StaffAccountForm from '../../components/StaffAccountForm.vue';
import StaffIdentity from '../../components/StaffIdentity.vue';
const accounts=ref([]),activities=ref([]),creating=ref(false),notice=ref('');
async function loadRelated(){try{[accounts.value,activities.value]=await Promise.all([platformOrganizerApi.accounts(route.params.id),platformOrganizerApi.activities(route.params.id)]);}catch(e){error.value=e.message;}}
async function created(){creating.value=false;notice.value='管理员账号已创建，首次登录需修改初始密码。';await loadRelated();}
async function load(){loading.value=true;error.value="";try{[organizer.value,accounts.value,activities.value]=await Promise.all([platformOrganizerApi.detail(route.params.id),platformOrganizerApi.accounts(route.params.id),platformOrganizerApi.activities(route.params.id)]);}catch(e){error.value=e?.message||"主办方详情加载失败";}finally{loading.value=false;}}onMounted(load);
</script>
<style scoped>
.archive-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:15px}.archive-heading h2{margin:0}.panel{overflow:auto}.staff-table{min-width:550px}
.content{padding:34px;max-width:1000px}.title-row{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.eyebrow{color:#6f7690;font-size:13px;margin-bottom:10px}h1{margin:0 0 8px;font-size:30px}.title-row p{margin:0;color:#6e7387}.back-link{color:#0d50dc;text-decoration:none;padding-top:28px}.panel{background:#fff;border:1px solid #e1e5ef;border-radius:10px;padding:24px;margin-bottom:20px}.hero{display:flex;align-items:center;gap:18px}.avatar{width:64px;height:64px;border-radius:14px;background:#dfe8ff;color:#0d50dc;display:grid;place-items:center;font-size:28px;font-weight:700}.hero h2{margin:10px 0 4px}.hero p{margin:0;color:#737b90}.status{display:inline-block;padding:5px 9px;border-radius:12px;font-size:12px}.status-PENDING{background:#fff3dc;color:#a86b00}.status-APPROVED{background:#e0f8e9;color:#16834a}.status-REJECTED,.status-DISABLED{background:#ffe7e7;color:#c53a43}.panel>h2{margin:0 0 20px;font-size:18px}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;margin:0}dt{font-size:13px;color:#858b9d;margin-bottom:7px}dd{margin:0;color:#252a3a}.notice{background:#f4f6ff;border-color:#dce4ff}.notice p{color:#616b85;margin:10px 0 0}.state{color:#737b90}.error{color:#c53a43}@media(max-width:700px){.content{padding:20px 14px}.title-row{display:block}.back-link{display:inline-block;padding-top:14px}dl{grid-template-columns:1fr}}
</style>
